# -*- coding: utf-8 -*-
import html as _html

def esc(s: str) -> str: return _html.escape(s.strip("\n"), quote=False)
def code(label: str, src: str) -> str: return f'''          <div class="code-block">\n            <div class="code-header">\n              <span class="code-lang">{_html.escape(label)}</span>\n              <button class="copy-btn" onclick="copyCode(this)">📋 コピー</button>\n            </div>\n            <pre><code>{esc(src)}</code></pre>\n          </div>\n'''
def concept(title: str, body: str) -> str: return f'''          <div class="concept-box">\n            <h4>💡 {title}</h4>\n            {body}\n          </div>\n'''
def explain(title: str, body: str) -> str: return f'''          <div class="explanation-box">\n            <h4>{title}</h4>\n            {body}\n          </div>\n'''
def warn(title: str, body: str) -> str: return f'''          <div class="warning-box">\n            <h4>⚠️ {title}</h4>\n            {body}\n          </div>\n'''
def tips(body: str) -> str: return f'''          <div class="explanation-box">\n            <h4>💼 Tips：実務・試験で遭遇する勘所と落とし穴</h4>\n            {body}\n          </div>\n'''
def table(headers, rows) -> str:
    th = "".join(f'<td style="padding:0.45rem; font-weight:bold;">{h}</td>' for h in headers)
    trs = "".join('<tr style="border-bottom:1px solid var(--color-border);">' + "".join(f'<td style="padding:0.4rem; vertical-align:top;">{c}</td>' for c in r) + "</tr>" for r in rows)
    return f'<table style="width:100%; border-collapse:collapse; margin:1rem 0; font-size:0.92em;"><tr style="background:rgba(99,102,241,0.15);">{th}</tr>{trs}</table>'
def lesson(tab: str, n: int, title: str, *parts: str) -> str:
    sec = f"{tab}-{n}"
    return f'''      <article class="lesson-card" data-section="{sec}" id="{tab}-lesson-{n}">\n        <div class="lesson-header" onclick="toggleSection(this)">\n          <div class="lesson-title-area">\n            <span class="lesson-number">{n:02d}</span>\n            <h3>{title}</h3>\n          </div>\n          <div class="lesson-controls">\n            <button class="complete-btn" onclick="event.stopPropagation(); toggleComplete('{sec}')" title="完了にする">\n              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>\n            </button>\n            <span class="chevron">▼</span>\n          </div>\n        </div>\n        <div class="lesson-body">\n{"".join(parts)}        </div>\n      </article>\n'''
def separator(color: str, title: str, body: str) -> str: return f'''      <div class="explanation-box" style="margin: 2rem 0; border-left: 4px solid {color}; background: rgba(255,255,255,0.03);">\n        <h4>{title}</h4>\n        <p>{body}</p>\n      </div>\n'''
def quiz_block(tab: str, title: str, intro: str) -> str: return f'''      <!-- {tab} Quiz -->\n      <div class="quiz-section" id="{tab}-quiz">\n        <div class="quiz-header">\n          <h3>📝 {title}</h3>\n        </div>\n        <p class="quiz-intro">{intro}</p>\n        <div id="{tab}-quiz-container"></div>\n        <div class="quiz-result" id="{tab}-quiz-result"></div>\n      </div>\n'''
def puzzle_block(tab: str) -> str: return f'''      <!-- {tab} Puzzle -->\n      <div class="puzzle-section" id="{tab}-puzzle-wrapper" style="margin-top: 2rem; border-top: 1px solid var(--color-border); padding-top: 2rem;">\n        <div class="quiz-header"><h3>🧩 並べ替えパズル</h3></div>\n        <p class="quiz-intro">ドラッグ＆ドロップで正しい順番に組み立ててください。</p>\n        <div class="puzzle-question" id="{tab}-puzzle-question" style="font-weight:bold; margin-bottom: 1rem; color: var(--color-text-primary);"></div>\n        <div class="puzzle-board">\n          <div class="puzzle-source" id="{tab}-puzzle-source"></div>\n          <div class="puzzle-dropzone" id="{tab}-puzzle-dropzone"><div class="dropzone-placeholder">ここにドロップしてコードを完成させる</div></div>\n        </div>\n        <div class="puzzle-controls" style="margin-top: 1rem; display: flex; gap: 1rem;">\n          <button class="check-btn" onclick="checkPuzzle('{tab}')" style="background: var(--accent); color: #fff; padding: 0.5rem 1rem; border-radius: 4px; border: none; cursor: pointer; font-weight:bold;">判定する</button>\n          <button class="reset-btn" onclick="loadPuzzle('{tab}')" style="background: var(--color-surface); color: var(--color-text-primary); padding: 0.5rem 1rem; border-radius: 4px; border: 1px solid var(--color-border); cursor: pointer;">リセット</button>\n        </div>\n        <div class="quiz-result" id="{tab}-puzzle-result" style="margin-top: 1rem;"></div>\n      </div>\n'''
def fill_block(tab: str) -> str: return f'''      <!-- {tab} Fill-in -->\n      <div class="quiz-section fill-section" id="{tab}-fill">\n        <div class="quiz-header"><h3>✍️ 穴埋め演習</h3></div>\n        <p class="quiz-intro">空欄（____）に入る語句を入力し、「答え合わせ」を押してください。大文字・小文字は区別しません。</p>\n        <div id="{tab}-fill-container"></div>\n        <div class="quiz-result" id="{tab}-fill-result"></div>\n      </div>\n'''
def mission_block(tab: str) -> str: return f'''      <!-- {tab} Mini Mission -->\n      <div class="quiz-section mission-section" id="{tab}-mission">\n        <div class="quiz-header"><h3>🎯 Mini Mission — 設計演習と自己評価</h3></div>\n        <p class="quiz-intro">PDI（個人開発インスタンス）で実際に手を動かし、ルーブリックで自己評価してください。チェック状態はブラウザに保存されます。</p>\n        <div id="{tab}-mission-container"></div>\n      </div>\n'''
